@extends('layouts.app') @section('title','Equipment') @section('content')<x-page-header :title="$equipment->exists?'Edit equipment':'Add equipment'"/><form method="POST" action="{{ $equipment->exists?route('equipment.update',$equipment):route('equipment.store') }}" class="content-card">@csrf @if($equipment->exists)@method('PUT')@endif<div class="row g-3">@foreach([['name','Name','text'],['type','Type','text'],['brand','Brand','text'],['model','Model','text'],['serial_number','Serial number','text'],['purchase_date','Purchase date','date'],['cost','Cost','number']] as [$n,$l,$t])<div class="col-md-6"><label>{{ $l }}</label><input name="{{ $n }}" type="{{ $t }}" value="{{ old($n,$equipment->$n instanceof \Carbon\Carbon?$equipment->$n->format('Y-m-d'):$equipment->$n) }}" class="form-control"></div>@endforeach<div class="col-md-6"><label>Condition</label><select name="condition" class="form-select">@foreach(['excellent','good','fair','damaged'] as $s)<option @selected(old('condition',$equipment->condition?:'good')===$s)>{{ $s }}</option>@endforeach</select></div><div class="col-md-6"><label>Status</label><select name="status" class="form-select">@foreach(['available','assigned','in_use','maintenance','damaged','lost'] as $s)<option @selected(old('status',$equipment->status?:'available')===$s) value="{{ $s }}">{{ str($s)->replace('_',' ')->title() }}</option>@endforeach</select></div></div><button class="btn btn-primary mt-3">Save</button></form>@endsection
